import http from 'node:http';
import crypto from 'node:crypto';
import worker from '../../worker/index.js';
const origin='http://127.0.0.1:4185',cookie='ps_owner='+ '7'.repeat(32),items=new Map();
const bucket={async put(key,value){items.set(key,value);return {}},async get(key){const value=items.get(key);return value==null?null:{body:value,json:async()=>JSON.parse(value)}},async delete(key){items.delete(key)},async list({prefix='',limit=50}){return {objects:[...items.keys()].filter(k=>k.startsWith(prefix)).slice(0,limit).map(key=>({key}))}}};
const env={RECORDINGS:bucket};
const first='Copy the clam into the sheet.',second='If status is approved, calculate quantity times price into a new total column.';
const recordId='8'.repeat(32),owner=crypto.createHash('sha256').update('7'.repeat(32)).digest('hex');
await bucket.put(`owners/${owner}/${recordId}.json`,JSON.stringify({id:recordId,kind:'notes',filename:'Synthetic source check',mime:null,size:0,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),revision:1,transcript:first+' '+second,transcriptSource:'Synthetic fixture',reviewed:true,segments:[{text:first,time:0,end:2},{text:second,time:3,end:6}],result:{title:'Synthetic check',summary:'Disposable test source.',steps:[{title:'Copy a field',instruction:first,evidence:first,automation:'candidate',integration:'none',approval:'not-required',uncertainties:[]},{title:'Conditional calculation',instruction:second,evidence:second,automation:'candidate',integration:'none',approval:'not-required',uncertainties:[]}],actions:[]},method:'manual'}));
http.createServer(async(req,res)=>{try{const request=new Request(origin+req.url,{method:req.method,headers:{...req.headers,cookie},...(!['GET','HEAD'].includes(req.method)?{body:req,duplex:'half'}:{})});let response;if(req.url.startsWith('/api/local/sharing/status'))response=Response.json({available:true,connected:true,destination:'https://vercel-logged-out.vercel.app',links:{}});else if(req.url.startsWith('/api/local/status'))response=Response.json({available:false,ai:false,localSpeech:false});else if(req.url.startsWith('/api/chatgpt/status'))response=Response.json({available:false,ai:false,accounts:[],account:null});else if(req.url.startsWith('/api/desktop/status'))response=Response.json({available:false});else response=await worker.fetch(request,env);res.writeHead(response.status,Object.fromEntries(response.headers));res.end(Buffer.from(await response.arrayBuffer()));}catch(error){res.writeHead(500);res.end(error.message)}}).listen(4185,'127.0.0.1',()=>console.log(origin+'/recording.html?record='+recordId));
